package com.primehr.rsp.evaluation;
import com.primehr.integration.administrative.*; import com.primehr.integration.humanresource.*; import com.primehr.positionprofile.api.*; import com.primehr.positionprofile.domain.*; import com.primehr.rsp.applicant.domain.*; import com.primehr.rsp.applicant.infrastructure.*; import com.primehr.rsp.domain.*; import com.primehr.rsp.evaluation.api.EvaluationProceedingDtos.*; import com.primehr.rsp.evaluation.application.*; import com.primehr.rsp.evaluation.domain.*; import com.primehr.rsp.evaluation.infrastructure.*; import com.primehr.rsp.infrastructure.*; import com.primehr.rsp.screening.domain.*; import com.primehr.rsp.screening.infrastructure.*; import com.primehr.shared.exception.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.context.*; import org.springframework.security.access.*; import org.springframework.test.context.*; import org.springframework.transaction.annotation.*; import java.math.*; import java.time.*; import java.util.*; import static org.assertj.core.api.Assertions.*;
@SpringBootTest @ActiveProfiles("test") @Transactional class EvaluationProceedingServiceIntegrationTest {
 @Autowired EvaluationProceedingService service;@Autowired RecruitmentPlanRepository plans;@Autowired VacancyRequestRepository vacancies;@Autowired VacancyPublicationRepository publications;@Autowired EvaluationPolicyRepository policies;@Autowired EvaluationStageRepository stages;@Autowired EvaluationCriterionRepository criteria;@Autowired PublicationEvaluationPolicyRepository bindings;@Autowired CommitteeRepository committees;@Autowired CommitteeMemberRepository members;@Autowired PositionApplicationRepository applications;@Autowired ScreeningCaseRepository screening;
 @Test void exactQualifiedAdmissionOpenAccessAndStaleConflictAreEnforced(){Fixture f=fixture("OK");ProceedingResponse draft=service.create("TEST-AGENCY",new CreateProceeding(f.publication.getId(),f.publication.getVersion(),f.committee.getId(),f.committee.getVersion(),f.planned),"COORD",null);assertThatThrownBy(()->service.get("TEST-AGENCY",draft.id(),"OUTSIDER")).isInstanceOf(AccessDeniedException.class);ProceedingResponse admitted=service.admit("TEST-AGENCY",draft.id(),new AdmitCandidates(draft.recordVersion(),List.of(new CandidateInput(f.application.getId(),f.application.getVersion(),f.screening.getVersion()))),"COORD",null);assertThat(admitted.candidates()).hasSize(1);assertThat(admitted.candidateSetRevision()).isEqualTo(1);assertThatThrownBy(()->service.admit("TEST-AGENCY",draft.id(),new AdmitCandidates(draft.recordVersion(),List.of(new CandidateInput(f.application.getId(),f.application.getVersion(),f.screening.getVersion()))),"COORD",null)).isInstanceOf(OptimisticConflictException.class);ProceedingResponse opened=service.open("TEST-AGENCY",draft.id(),new Transition(admitted.recordVersion(),null),"COORD",null);assertThat(opened.status()).isEqualTo("OPEN");}
 @Test void nonQualifiedWrongVacancyAndSupersededScreeningCannotEnterOrOpen(){Fixture f=fixture("BAD");PositionApplication notQualified=new PositionApplication("TEST-AGENCY","OTHER",f.publication,1);notQualified.submit("ACK","NOTICE",1,"{}","{}","[]","{}",Instant.now());notQualified=applications.saveAndFlush(notQualified);ProceedingResponse draft=service.create("TEST-AGENCY",new CreateProceeding(f.publication.getId(),f.publication.getVersion(),f.committee.getId(),f.committee.getVersion(),f.planned),"COORD",null);PositionApplication finalNotQualified=notQualified;assertThatThrownBy(()->service.admit("TEST-AGENCY",draft.id(),new AdmitCandidates(draft.recordVersion(),List.of(new CandidateInput(finalNotQualified.getId(),finalNotQualified.getVersion(),f.screening.getVersion()))),"COORD",null)).hasMessageContaining("QUALIFIED");ProceedingResponse admitted=service.admit("TEST-AGENCY",draft.id(),new AdmitCandidates(draft.recordVersion(),List.of(new CandidateInput(f.application.getId(),f.application.getVersion(),f.screening.getVersion()))),"COORD",null);f.screening.supersede();screening.saveAndFlush(f.screening);assertThatThrownBy(()->service.open("TEST-AGENCY",draft.id(),new Transition(admitted.recordVersion(),null),"COORD",null)).hasMessageContaining("current qualified source");}
 @Test void changedCommitteeSourceBlocksOpeningWithoutRewritingTheSnapshot(){Fixture f=fixture("SOURCE");ProceedingResponse draft=service.create("TEST-AGENCY",new CreateProceeding(f.publication.getId(),f.publication.getVersion(),f.committee.getId(),f.committee.getVersion(),f.planned),"COORD",null);ProceedingResponse admitted=service.admit("TEST-AGENCY",draft.id(),new AdmitCandidates(draft.recordVersion(),List.of(new CandidateInput(f.application.getId(),f.application.getVersion(),f.screening.getVersion()))),"COORD",null);String immutableSnapshot=admitted.committeeSnapshot();f.committee.supersede(f.planned.plusDays(1));committees.saveAndFlush(f.committee);assertThatThrownBy(()->service.open("TEST-AGENCY",draft.id(),new Transition(admitted.recordVersion(),null),"COORD",null)).hasMessageContaining("committee source changed");assertThat(service.get("TEST-AGENCY",draft.id(),"COORD").committeeSnapshot()).isEqualTo(immutableSnapshot);}
 @Test void cancellationRequiresAReasonAndReleasesThePublicationForASuccessorProceeding(){Fixture f=fixture("CANCEL");ProceedingResponse draft=service.create("TEST-AGENCY",new CreateProceeding(f.publication.getId(),f.publication.getVersion(),f.committee.getId(),f.committee.getVersion(),f.planned),"COORD",null);assertThatThrownBy(()->service.cancel("TEST-AGENCY",draft.id(),new Transition(draft.recordVersion()," "),"COORD",null)).hasMessageContaining("reason");ProceedingResponse cancelled=service.cancel("TEST-AGENCY",draft.id(),new Transition(draft.recordVersion(),"Authorized restart"),"COORD",null);assertThat(cancelled.status()).isEqualTo("CANCELLED");assertThat(cancelled.cancellationReason()).isEqualTo("Authorized restart");ProceedingResponse successor=service.create("TEST-AGENCY",new CreateProceeding(f.publication.getId(),f.publication.getVersion(),f.committee.getId(),f.committee.getVersion(),f.planned),"COORD",null);assertThat(successor.id()).isNotEqualTo(cancelled.id());}
 private Fixture fixture(String suffix){LocalDate planned=LocalDate.now().plusDays(10);VacancyPublication publication=publication(suffix);EvaluationPolicy policy=new EvaluationPolicy("TEST-AGENCY","EV-"+suffix,"Evaluation","Generic","MSP",1,null,2,EvaluationPolicy.Rounding.HALF_UP,EvaluationPolicy.TieRule.COMPETITION);policy.publish(LocalDate.now().minusYears(1),null,"publisher",Instant.now());policy=policies.saveAndFlush(policy);EvaluationStage stage=stages.saveAndFlush(new EvaluationStage("TEST-AGENCY",policy.getId(),"EXAM","Exam",null,EvaluationStage.Type.WRITTEN_EXAMINATION,EvaluationStage.Mode.SCORED,new BigDecimal("100"),new BigDecimal("100"),null,1,true,0));criteria.saveAndFlush(new EvaluationCriterion("TEST-AGENCY",policy.getId(),stage.getId(),"TOTAL","Total",null,new BigDecimal("100"),new BigDecimal("100"),false,0));String policySnapshot="{}";PublicationEvaluationPolicy binding=bindings.saveAndFlush(new PublicationEvaluationPolicy("TEST-AGENCY",publication,policy,policySnapshot,EvaluationPolicyServiceImpl.hash(policySnapshot),"publisher",Instant.now()));Committee committee=new Committee("TEST-AGENCY","C-"+suffix,"Board","EO",1,1,null);committee.publish(LocalDate.now().minusYears(1),null,"publisher",Instant.now());committee=committees.saveAndFlush(committee);members.saveAllAndFlush(List.of(new CommitteeMember("TEST-AGENCY",committee.getId(),"CHAIR",CommitteeMember.Role.CHAIRPERSON,null,LocalDate.now().minusYears(1),null),new CommitteeMember("TEST-AGENCY",committee.getId(),"COORD",CommitteeMember.Role.SECRETARIAT,null,LocalDate.now().minusYears(1),null)));PositionApplication application=new PositionApplication("TEST-AGENCY","APPLICANT-"+suffix,publication,1);application.submit("ACK-"+suffix,"NOTICE",1,"{}","{}","[]","{}",Instant.now());application.beginScreening();application=applications.saveAndFlush(application);ScreeningCase screen=new ScreeningCase("TEST-AGENCY",application,publication.getId(),"SCREEN-POL",1,1,null,"{}","{}","SCREENER",Instant.now());screen.submit(ScreeningCase.Outcome.QUALIFIED,null,null,null,"Qualified","SCREENER",Instant.now());screen.finalizeDecision(ScreeningCase.Outcome.QUALIFIED,"VALIDATOR",Instant.now());screen=screening.saveAndFlush(screen);application.completeScreening(PositionApplication.Status.QUALIFIED);application=applications.saveAndFlush(application);return new Fixture(publication,committee,application,screen,planned);}
 private VacancyPublication publication(String suffix){RecruitmentPlan plan=new RecruitmentPlan("TEST-AGENCY","P-"+suffix,"Plan",LocalDate.now().minusYears(1),LocalDate.now().plusYears(1),null);plan.submit("s",Instant.now());plan.approve("a",Instant.now());plans.saveAndFlush(plan);VacancyRequest vacancy=new VacancyRequest("TEST-AGENCY",plan,VacancyType.ACTUAL,null,null,null,null,"HIGH",null,"Required",new AdministrativeRspPositionSource(3L,"Plantilla",14L,"Accountant",19L,1L,2L,"FIN","Finance",7L,2,"Degree","Training","Experience","Eligibility",null,"CSC",LocalDate.now().minusYears(1),null,"a".repeat(64),Instant.now()),new HumanResourcePlantillaOccupancy(3L,false,null,null,"b".repeat(64),Instant.now()),new PositionProfileResponse("profile-"+suffix,"Profile",null,PositionProfileStatus.ACTIVE,1,null,LocalDate.now().minusYears(1),null,3L,1L,"s",Instant.now(),"a",Instant.now(),null,List.of()));vacancy.submit("s",Instant.now());vacancy.authorize("a",Instant.now());vacancies.saveAndFlush(vacancy);VacancyPublication p=new VacancyPublication("TEST-AGENCY",vacancy,VacancyVisibility.BOTH,LocalDate.now().minusDays(20),LocalDate.now().minusDays(10),"Apply","HR","Notice",Instant.now());p.submit("s",Instant.now());p.approve("a",Instant.now());p.publish("p",Instant.now());p.close("c",Instant.now());return publications.saveAndFlush(p);}private record Fixture(VacancyPublication publication,Committee committee,PositionApplication application,ScreeningCase screening,LocalDate planned){}
}
